## 5. Validate the Evaluation Table

A fair comparison requires:

- exactly 10 query games;
- exactly 4 models;
- 10 recommendations per query and model;
- no duplicate query–candidate pair within a model; and
- no self-recommendations.

The expected master table therefore contains 400 rows.

def game_feature_set(row):
    features = set()

    # Genres are stored as text representing a list.
    try:
        genres = ast.literal_eval(row["genres"])
    except (ValueError, SyntaxError, TypeError):
        genres = []

    # Tags are stored as text representing a dictionary.
    try:
        tags = ast.literal_eval(row["tags"])
    except (ValueError, SyntaxError, TypeError):
        tags = {}

    if isinstance(genres, list):
        features.update(
            str(genre).lower()
            for genre in genres
        )

    if isinstance(tags, dict):
        features.update(
            str(tag).lower()
            for tag in tags.keys()
        )

    return features


# Build one feature set for every game.
game_features = {
    row["appid"]: game_feature_set(row)
    for _, row in games.iterrows()
}


def jaccard_similarity(set_a, set_b):
    union = set_a | set_b

    if not union:
        return 0.0

    return len(set_a & set_b) / len(union)


def diversity_for_list(appids):
    dissimilarities = []

    for i in range(len(appids)):
        for j in range(i + 1, len(appids)):
            features_a = game_features.get(appids[i], set())
            features_b = game_features.get(appids[j], set())

            similarity = jaccard_similarity(
                features_a,
                features_b,
            )

            dissimilarities.append(
                1 - similarity
            )

    if not dissimilarities:
        return 0.0

    return np.mean(dissimilarities)

diversity_records = []

for (model_name, query_game), group in evaluation_with_labels.groupby(
    ["model", "query_game"]
):
    appids = (
        group
        .sort_values("rank")["appid"]
        .tolist()
    )

    diversity_records.append(
        {
            "model": model_name,
            "query_game": query_game,
            "diversity_at_10": diversity_for_list(appids),
        }
    )

diversity_by_query = pd.DataFrame(
    diversity_records
)

model_diversity_summary = (
    diversity_by_query
    .groupby("model")
    .agg(
        diversity_at_10=("diversity_at_10", "mean")
    )
    .reset_index()
)

model_diversity_summary["diversity_at_10"] = (
    model_diversity_summary["diversity_at_10"]
    .round(4)
)

display(
    model_diversity_summary.sort_values(
        "diversity_at_10",
        ascending=False,
    )

# Give the runtime tables clear model labels.
metadata_runtime["model"] = "Metadata"
semantic_runtime["model"] = "Semantic"
graph_runtime["model"] = "Graph"


# Build the end-to-end Hybrid runtime.
hybrid_end_to_end = metadata_runtime[
    ["query_game", "runtime_seconds"]
].rename(
    columns={"runtime_seconds": "metadata_runtime"}
)

hybrid_end_to_end = hybrid_end_to_end.merge(
    semantic_runtime[
        ["query_game", "runtime_seconds"]
    ].rename(
        columns={"runtime_seconds": "semantic_runtime"}
    ),
    on="query_game",
)

hybrid_end_to_end = hybrid_end_to_end.merge(
    graph_runtime[
        ["query_game", "runtime_seconds"]
    ].rename(
        columns={"runtime_seconds": "graph_runtime"}
    ),
    on="query_game",
)

hybrid_end_to_end = hybrid_end_to_end.merge(
    hybrid_runtime[
        ["query_game", "runtime_seconds"]
    ].rename(
        columns={"runtime_seconds": "fusion_runtime"}
    ),
    on="query_game",
)

hybrid_end_to_end["runtime_seconds"] = (
    hybrid_end_to_end["metadata_runtime"]
    + hybrid_end_to_end["semantic_runtime"]
    + hybrid_end_to_end["graph_runtime"]
    + hybrid_end_to_end["fusion_runtime"]
)

hybrid_end_to_end["model"] = "Hybrid"


# Combine all runtime observations.
runtime_rows = pd.concat(
    [
        metadata_runtime[["model", "query_game", "runtime_seconds"]],
        semantic_runtime[["model", "query_game", "runtime_seconds"]],
        graph_runtime[["model", "query_game", "runtime_seconds"]],
        hybrid_end_to_end[["model", "query_game", "runtime_seconds"]],
    ],
    ignore_index=True,
)


runtime_summary = (
    runtime_rows
    .groupby("model")
    .agg(
        mean_runtime_seconds=("runtime_seconds", "mean"),
        median_runtime_seconds=("runtime_seconds", "median"),
        min_runtime_seconds=("runtime_seconds", "min"),
        max_runtime_seconds=("runtime_seconds", "max"),
    )
    .reset_index()
)

runtime_summary[
    [
        "mean_runtime_seconds",
        "median_runtime_seconds",
        "min_runtime_seconds",
        "max_runtime_seconds",
    ]
] = runtime_summary[
    [
        "mean_runtime_seconds",
        "median_runtime_seconds",
        "min_runtime_seconds",
        "max_runtime_seconds",
    ]
].round(4)

display(
    runtime_summary.sort_values(
        "mean_runtime_seconds"
    )

final_evaluation_summary = model_evaluation_summary.merge(
    model_diversity_summary,
    on="model",
)

final_evaluation_summary = final_evaluation_summary.merge(
    runtime_summary[
        ["model", "mean_runtime_seconds"]
    ],
    on="model",
)

final_evaluation_summary = final_evaluation_summary.rename(
    columns={
        "precision_at_10": "Precision@10",
        "ndcg_at_10": "NDCG@10",
        "diversity_at_10": "Diversity@10",
        "mean_runtime_seconds": "Mean Runtime (s)",
    }
)

final_evaluation_summary = final_evaluation_summary.sort_values(
    "NDCG@10",
    ascending=False,
).reset_index(drop=True)

display(final_evaluation_summary)

rrf_additional_labels = pd.DataFrame(
    [
        {
            "query_appid": 548430,
            "appid": 3197230,
            "relevance_score": 1,
        },
        {
            "query_appid": 289070,
            "appid": 1011390,
            "relevance_score": 2,
        },
        {
            "query_appid": 413150,
            "appid": 1350840,
            "relevance_score": 2,
        },
    ]
)

rrf_relevance_labels = pd.concat(
    [
        relevance_labels,
        rrf_additional_labels,
    ],
    ignore_index=True,
).drop_duplicates(
    subset=["query_appid", "appid"],
    keep="last",
)

sensitivity_with_labels = rrf_sensitivity_results.merge(
    rrf_relevance_labels,
    on=["query_appid", "appid"],
    how="left",
)

print("Main evaluation labels:", len(relevance_labels))
print("Sensitivity label pool:", len(rrf_relevance_labels))
print(
    "Missing sensitivity labels:",
    sensitivity_with_labels["relevance_score"].isna().sum()
)

assert len(relevance_labels) == 246
assert len(rrf_relevance_labels) == 249
assert sensitivity_with_labels["relevance_score"].isna().sum() == 0
